        new_title=data.title,
        new_size=data.size,
        new_description=data.description,
        new_sub=modelsv2.SubItem(new_sub_name=data.sub.name),
        new_multi=[modelsv2.SubItem(new_sub_name=s.name) for s in data.multi],
    )


